$('#copyright-year').textContent=new Date().getFullYear();

const productTrigger=$('#product-trigger'), productPanel=$('#product-menu');
function closeProductMenu(returnFocus=false){productTrigger.setAttribute('aria-expanded','false');productPanel.hidden=true;if(returnFocus)productTrigger.focus();}
productTrigger.addEventListener('click',()=>{const opening=productPanel.hidden;productPanel.hidden=!opening;productTrigger.setAttribute('aria-expanded',String(opening));});
document.addEventListener('click',e=>{if(!e.target.closest('.product-menu'))closeProductMenu();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!productPanel.hidden)closeProductMenu(true);});
document.addEventListener('focusin',e=>{if(!e.target.closest('.product-menu')&&!productPanel.hidden)closeProductMenu();});
productPanel.querySelector('.menu-overview').addEventListener('click',()=>closeProductMenu());

function openDialog(dialog,trigger){const returnTarget=trigger?.closest('dialog[open]')?dialogTrigger:trigger;closeProductMenu();document.querySelectorAll('dialog[open]').forEach(d=>d.close());dialogTrigger=returnTarget;dialog.showModal();document.body.classList.add('modal-open');}
document.querySelectorAll('dialog').forEach(dialog=>{
  dialog.querySelectorAll('[data-close]').forEach(button=>button.addEventListener('click',()=>dialog.close()));
  dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
  dialog.addEventListener('close',()=>{if(!document.querySelector('dialog[open]')){document.body.classList.remove('modal-open');if(dialogTrigger?.offsetParent!==null)dialogTrigger?.focus();else $('#mobile-trigger').focus();}});
});
$('#mobile-trigger').addEventListener('click',e=>openDialog($('#mobile-menu'),e.currentTarget));
$('#mobile-menu').querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>$('#mobile-menu').close()));

function updateRequestLabels(){
  $('#request-title').textContent=t(requestType+'Title');
  $('#request-description').textContent=t(requestType+'Description');
  $('#request-title').style.whiteSpace='pre-line';
  $('.consult-field').hidden=requestType!=='consult';
}
