const now=new Date();const localDate=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;
$('#request-form').elements.date.min=localDate;
$('#request-form').addEventListener('submit',e=>{
  e.preventDefault();const form=e.currentTarget;const data=Object.fromEntries(new FormData(form));
  for(const key in data)data[key]=data[key].trim();
  document.querySelectorAll('.field-error').forEach(el=>el.textContent='');
  form.querySelectorAll('[aria-invalid]').forEach(el=>el.removeAttribute('aria-invalid'));
  const errors={};
  if(data.name.length<2)errors.name=t('nameError');
  if(!data.company)errors.company=t('companyError');
  if(!data.email&&!data.phone)errors.email=t('contactError');
  if(data.email&&!form.elements.email.validity.valid)errors.email=t('emailError');
  if(data.phone&&!/^[+\d\s().-]{6,30}$/.test(data.phone))errors.phone=t('phoneError');
  if(data.message.length<10)errors.message=t('messageError');
  if(requestType==='consult'&&data.date&&data.date<localDate)errors.date=t('dateError');
  if(Object.keys(errors).length){for(const [key,message]of Object.entries(errors)){form.elements[key].setAttribute('aria-invalid','true');document.querySelector(`[data-error-for="${key}"]`).textContent=message;}form.elements[Object.keys(errors)[0]].focus();return;}
  const group=categories.find(c=>c.slug===data.category)?.[language]||t('unknown');
  draftText=[`${t('name')}: ${data.name}`,`${t('company')}: ${data.company}`,`Email: ${data.email||t('unspecified')}`,`${t('phone')}: ${data.phone||t('unspecified')}`,`${t('productGroup')}: ${group}`,...(requestType==='consult'?[`${t('preferredDate')}: ${data.date||t('unspecified')}`]:[]),'',`${t('message')}:`,data.message,'',isFactoryPage?(language==='vi'?'Nguồn: Hồ sơ doanh nghiệp HotPrint':'Source: HotPrint company profile'):isCatalogPage?(language==='vi'?'Nguồn: Nhãn hàng & catalog HotPrint':'Source: HotPrint hang tags and catalogues'):isLabelPage?(language==='vi'?'Nguồn: Nhãn dán decal HotPrint':'Source: HotPrint adhesive labels'):isBagPage?(language==='vi'?'Nguồn: Túi giấy HotPrint':'Source: HotPrint paper bags'):isRigidPage?(language==='vi'?'Nguồn: Hộp cứng cao cấp HotPrint':'Source: HotPrint premium rigid boxes'):isCartonPage?(language==='vi'?'Nguồn: Hộp carton in màu HotPrint':'Source: HotPrint printed corrugated boxes'):isFoldingPage?(language==='vi'?'Nguồn: Hộp giấy mềm HotPrint':'Source: HotPrint folding cartons'):isProductsPage?(language==='vi'?'Nguồn: Tổng quan sản phẩm HotPrint':'Source: HotPrint product overview'):t('source')].join('\n');
  const subject=t('emailSubject')+t(requestType==='quote'?'quote':'consult');
  const url=`mailto:Info@HotPrint.vn?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(draftText)}`;
  window.location.href=url;
  $('#form-status').textContent=t('draftReady');$('#copy-draft').hidden=false;
});
let toastTimer;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
async function copyText(text,fallback){try{await navigator.clipboard.writeText(text);toast(t('copied'));return true;}catch{if(fallback){fallback.value=text;fallback.hidden=false;fallback.focus();fallback.select();}return false;}}
$('#copy-draft').addEventListener('click',async()=>{if(!await copyText(draftText,$('#draft-fallback')))$('#form-status').textContent=t('copyManual');});

function showInfo(type,trigger){
  if(type==='terms'){window.open(termsPath(language),'_blank','noopener');return;}
  if(type==='privacy'){window.open(privacyPath(language),'_blank','noopener');return;}
  $('#info-title').textContent=t(type);$('#info-content').replaceChildren(...t(type+'Text').map(text=>{const p=document.createElement('p');p.textContent=text;return p;}));
  $('#info-dialog').querySelector('.button').hidden=false;
  openDialog($('#info-dialog'),trigger);
}
document.querySelectorAll('[data-info]').forEach(button=>button.addEventListener('click',()=>showInfo(button.dataset.info,button)));
document.querySelectorAll('[data-call]').forEach(link=>link.addEventListener('click',e=>{
  if(matchMedia('(max-width:768px)').matches)return;
  e.preventDefault();$('#info-title').textContent=t('callTitle');
  $('#info-content').innerHTML=`<p>${t('callDescription')}</p><p class="phone-large"><a href="tel:+84903032686">0903.032.686</a></p><button class="copy-phone" id="copy-phone">${icon('copy')}<span>${t('copyPhone')}</span></button><p><a href="tel:+84903032686">${t('callNow')} →</a></p>`;
  $('#info-dialog').querySelector('.button').hidden=true;
  $('#copy-phone').addEventListener('click',async()=>{if(!await copyText('0903032686'))toast('0903.032.686');});
  openDialog($('#info-dialog'),link);
}));
let framePending=false;
function onScroll(){if(framePending)return;framePending=true;requestAnimationFrame(()=>{$('#site-header').classList.toggle('scrolled',scrollY>90);$('#mobile-contact-bar').classList.toggle('visible',scrollY>($('.hero, .catalog-hero')?.offsetHeight||420)-90);framePending=false;});}
window.addEventListener('scroll',onScroll,{passive:true});window.addEventListener('resize',onScroll);onScroll();
